+describe('collectReadinessFailureEvidence — scoping: Unhealthy event in staging, healthy pod in default excluded', () => {
+  const ctx = makeContext({
+    events: [
+      makeEvent('Unhealthy', 'Readiness probe failed', 'api', 'Pod', 'staging'),
